CREATE TABLE IF NOT EXISTS `events` (
  id INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT,
  client_id INTEGER NOT NULL,
  event_type TEXT NOT NULL,
  event_date DATE NOT NULL,
  start_time TIME,
  end_time TIME,
  location TEXT,
  status TEXT NOT NULL DEFAULT 'NEW'
    CHECK(status IN ('NEW','ASSIGNED','SHOOT_DONE','DELIVERED','CANCELLED')),
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, `Service Type` TEXT, amount REAL DEFAULT 0, Stage TEXT, venue TEXT, guest_count INTEGER, enquiry_message TEXT, source TEXT DEFAULT 'WEBSITE', paid_amount REAL DEFAULT 0, `advance` REAL, amount_status INTEGER DEFAULT 0, total_amount REAL DEFAULT 0,

  FOREIGN KEY (client_id) REFERENCES clients(id)
);
