CREATE TABLE IF NOT EXISTS `studio_profile` (
    id INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT,
    studio_name VARCHAR(50) NOT NULL,
    description TEXT,
    image_url TEXT,
    address TEXT,
    phone VARCHAR(20),
    email VARCHAR(255),
    website TEXT,
    instagram VARCHAR(100),
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO studio_profile VALUES(1,'Rafia Digital Studio',unistr('Rafia Digital Studio is considered to be the best place for visual storytelling. Our love for photography knows no bounds, and weGÇÖve developed our techniques to perfection. Our photographers have a distinct artistic perspective, a recognizable signature, and a consistent quality across their work. Our main goal is to think creatively and provide exceptional customer service. And thatGÇÖs why we always stay updated on the latest trends including pre-wedding photography, post-wedding photography, and couple poses.\u000d\u000a\u000d\u000aWe make sure that our style of couple photography resonates with clients and leaves a lasting impression. We strive to capture images that are both visually spectacular and conceptually fascinating. Zero Gravity Photography is the best wedding photography in Chennai. Our website features an amazing showcase of our portfolio that shows our distinctive style, versatility, dedication to quality.\u000d\u000a\u000d\u000aIf you are seeking a talented team of photographers for your wedding, events or portraits, we take pride in saying that we have the expertise and passion to bring your vision to life. Our perseverance in the face of obstacles is what sets our company apart from the rest. With a high level of professionalism, we are reliable, punctual, and organized, ensuring a positive experience throughout the entire process. Explore our website, get inspired by our work, and find out why Zero Gravity Photography is the perfect choice for capturing your most memorable moments.'),'studio/1768498957115-WhatsApp Image 2025-12-27 at 6.31.12 PM.jpeg','D.No.19-13/4-23A, Old Raja Rajeswari Peta, Main Road, Vijayawada, NTR (Dist), 520001 ','9492809371','rafia243@gmail.com','https://www.youtube.com/@Kick_Gaming_Den','later we will update','2026-01-16 03:29:36');
CREATE TABLE user_sessions (
  id INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT,
  user_id INTEGER NOT NULL,

  device_name TEXT,
  ip_address TEXT,
  user_agent TEXT,

  is_current INTEGER DEFAULT 0,
  last_active DATETIME DEFAULT CURRENT_TIMESTAMP,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
