CREATE TABLE IF NOT EXISTS `event_cancellations` (
  id INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT,
  event_id INTEGER NOT NULL,
  admin_id INTEGER,
  reason TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP, admin_email TEXT,
  FOREIGN KEY (event_id) REFERENCES events(id)
);
