CREATE TABLE notifications (

  id INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT,

  type TEXT NOT NULL,

  payload TEXT,

  user_id INTEGER,

  is_read INTEGER NOT NULL DEFAULT 0,

